use spore_core::{creature_skin_queue_v1::{Queue,Step},creature_skin_seed_v1::seed,creature_skin_cube_walk_v1 as cube,native_sse::{self,Policy,SseError}};use std::io::Write;
fn field(p:[f32;3])->f32{native_sse::scoped(Policy::Mxcsr1f80,||Ok::<_,SseError>(1.5-((p[0]*p[0]+p[1]*p[1])+p[2]*p[2]))).unwrap()}
fn main(){let origin=[-2.;3];let groups=[[[0.;3];4]];let key=seed([4.;3],origin,1.,1.,&groups,1,Policy::Mxcsr1f80,field).unwrap();assert_eq!(key,0x020203);let mut q=Queue::from_seed(key,256,1024,1024).unwrap();let mut calls=Vec::new();loop{let i=q.cursor;match q.step(&cube::tables(),&cube::face_records(),origin,1.,0.01,0.001,Policy::Mxcsr1f80,field).unwrap(){Step::Drained=>break,Step::Processed=>{let e=q.entries[i];calls.push([e.packed|((e.faces as u32)<<24),e.class as u32]);assert!(calls.len()<=256)}}}assert!(q.entries.len()<=256);let mut out=Vec::new();for v in [q.cursor as u32,q.entries.len() as u32,q.geometry.status,calls.len() as u32]{out.extend(v.to_le_bytes())}for i in 0..256{let e=q.entries.get(i).copied().unwrap_or_default();for v in [e.packed|((e.faces as u32)<<24),e.known as u32|((e.class as u32)<<8)]{out.extend(v.to_le_bytes())}}for i in 0..256{for v in calls.get(i).copied().unwrap_or([0;2]){out.extend(v.to_le_bytes())}}for i in 0..0x4000{out.extend(q.keys[i].to_le_bytes());out.extend(q.indices[i].to_le_bytes())}std::io::stdout().write_all(&out).unwrap();}
